const baseUrl = $env.TAUTULLI_URL;
const apiKey = $env.TAUTULLI_API_KEY;

const after = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);

const res = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/api/v2`,
  qs: { apikey: apiKey, cmd: 'get_history', after, length: 1000 },
  json: true,
});

const rows = (res.response && res.response.data && res.response.data.data) || [];
const totalPlays = rows.length;
const users = new Set(rows.map((r) => r.friendly_name)).size;
const topTitles = Object.entries(
  rows.reduce((acc, r) => {
    acc[r.full_title] = (acc[r.full_title] || 0) + 1;
    return acc;
  }, {})
)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([title, count]) => `${title} (${count})`);

return [{
  json: {
    message: `This week: ${totalPlays} plays by ${users} user(s).\nTop watched:\n${topTitles.join('\n') || 'none'}`,
  },
}];
